(function() {
    function Molty_SmartRename() {
        var selectionNodes = selection.selectedNodes(0);
        if (selectionNodes.length === 0) return;

        scene.beginUndoRedoAccum("Molty_SmartRename");

        // Проверяем наличие рисунков (READ нод) в выделении
        var readNodes = selectionNodes.filter(function(n) { return node.type(n) === "READ"; });

        if (readNodes.length > 0) {
            // ЛОГИКА С РИСУНКАМИ: берем имя первого выбранного рисунка
            var baseName = node.getName(readNodes[0]);
            var newCompName = "C-" + baseName;
            var newPegName = baseName + "-P";
            var newGroupName = "Def-" + baseName;

            for (var i = 0; i < selectionNodes.length; i++) {
                var sNode = selectionNodes[i];
                var type = node.type(sNode);
                if (type === "COMPOSITE") safeRename(sNode, newCompName);
                else if (type === "PEG") safeRename(sNode, newPegName);
                else if (type === "GROUP") safeRename(sNode, newGroupName);
            }
        } else {
            // ЛОГИКА БЕЗ РИСУНКОВ: Пеги от Пегов, Композы от Композов
            for (var i = 0; i < selectionNodes.length; i++) {
                var sNode = selectionNodes[i];
                var type = node.type(sNode);

                if (type === "PEG") {
                    var childPegNames = [];
                    var numOutput = node.numberOfOutputLinks(sNode, 0);

                    for (var j = 0; j < numOutput; j++) {
                        var dNode = node.dstNode(sNode, 0, j);
                        // Берем имя только если это PEG
                        if (node.type(dNode) === "PEG") {
                            childPegNames.push(node.getName(dNode).replace("-P", ""));
                        }
                    }

                    applyNewName(sNode, childPegNames, "", "-P");
                } 

                else if (type === "COMPOSITE") {
                    var parentCompNames = [];
                    var numInput = node.numberOfInputPorts(sNode);

                    for (var j = 0; j < numInput; j++) {
                        var src = node.srcNode(sNode, j);
                        // Берем имя только если это COMPOSITE
                        if (src && node.type(src) === "COMPOSITE") {
                            var cName = node.getName(src).replace("C-", "");
                            if (parentCompNames.indexOf(cName) === -1) {
                                parentCompNames.push(cName);
                            }
                        }
                    }

                    applyNewName(sNode, parentCompNames, "C-", "");
                }
            }
        }

        scene.endUndoRedoAccum("Molty_SmartRename");
    }

    // Вспомогательная функция формирования имени и приставки _master
    function applyNewName(sNode, namesArray, prefix, suffix) {
        if (namesArray.length === 0) return;

        var finalName = "";
        if (namesArray.length === 1) {
            finalName = prefix + namesArray[0] + "_master" + suffix;
        } else {
            finalName = prefix + namesArray.join("+") + suffix;
        }

        safeRename(sNode, finalName);
    }

    // Безопасное переименование с проверкой уникальности
    function safeRename(sNode, newName) {
        if (!node.rename(sNode, newName)) {
            for (var x = 1; x < 2000; x++) {
                if (node.rename(sNode, newName + "_" + x)) break;
            }
        }
    }

    // Запуск
    Molty_SmartRename();

})();

(function() {
    function Molty_xPivot_to_zero() {
        var exeDialog = new private_exeDialog();

        scene.beginUndoRedoAccum("Molty_xPivot_to_zero");
        exeDialog.main();
        scene.endUndoRedoAccum("Molty_xPivot_to_zero");
    }

    function private_exeDialog() {
        this.main = function() {
            var selectionNodes = selection.selectedNodes(0);
            var successCount = 0;

            for (var i = 0; i < selectionNodes.length; ++i) {
                var sNode = selectionNodes[i];
                var type = node.type(sNode);

                // Работаем только с PEG и READ нодами
                if (type == "PEG" || type == "READ") {
                    var pivotAttr = node.getAttr(sNode, frame.current(), "pivot.x");

                    // Если атрибут pivot существует (проверка через наличие списка атрибутов)
                    if (pivotAttr) {
                        var yAttr = node.getAttr(sNode, frame.current(), "pivot.y");
                        var zAttr = node.getAttr(sNode, frame.current(), "pivot.z");

                        // Создаем новую точку с X = 0 и сохраняем текущие Y и Z
                        var newPivot = new Point3d(0, yAttr.doubleValue(), zAttr.doubleValue());

                        // Находим основной атрибут Pivot для установки значения Point3d
                        var myAttrs = node.getAttrList(sNode, frame.current(), "");
                        for (var j = 0; j < myAttrs.length; j++) {
                            if (myAttrs[j].name() == "Pivot") {
                                myAttrs[j].setValue(newPivot);
                                successCount = 1;
                                break;
                            }
                        }
                    }
                }
            }

            if (successCount == 1) {
                MessageBox.information("!!!Success!!!");
            }
        };
    }

    // Автоматический запуск функции при вызове скрипта
    Molty_xPivot_to_zero();

})();

(function() {
    function Molty_Backdrop() {
        var exeDialog = new private_exeDialog();

        scene.beginUndoRedoAccum("Molty_Backdrop");
        exeDialog.main();
        scene.endUndoRedoAccum("Molty_Backdrop");
    }

    function private_exeDialog() {
        this.main = function() {
            var selectionNodes = selection.selectedNodes(0);
            if (selectionNodes.length === 0) return; // Проверка на пустую выборку

            var sNode = selectionNodes[0];
            var MinX = node.coordX(sNode);
            var MinY = node.coordY(sNode);
            var MaxX = node.coordX(sNode);
            var MaxY = node.coordY(sNode);
            var BackdropName = "";

            for (var i = 0; i < selectionNodes.length; ++i) {
                sNode = selectionNodes[i];
                var x1 = node.coordX(sNode);
                var y1 = node.coordY(sNode);
                var x2 = node.coordX(sNode) + node.width(sNode);
                var y2 = node.coordY(sNode) + node.height(sNode);

                if (MinX > x1) { MinX = x1; }
                if (MinY > y1) { MinY = y1; }
                if (MaxX < x2) { MaxX = x2; }
                if (MaxY < y2) { MaxY = y2; }

                var source = node.srcNode(sNode, 0);

                if (selectionNodes.indexOf(source) == -1) {
                    BackdropName = node.getName(selectionNodes[i]);
                    BackdropName = BackdropName.replace("-G", "").replace("-P", "");
                }

                if ((node.type(selectionNodes[i]) == "PEG" || node.type(selectionNodes[i]) == "GROUP") && (source == "")) {
                    BackdropName = node.getName(selectionNodes[i]);
                    BackdropName = BackdropName.replace("-G", "").replace("-P", "");
                }
            }

            var myBackdrop = {
                "position": { "x": (MinX - 10), "y": (MinY - 10), "w": (MaxX - MinX + 20), "h": (MaxY - MinY + 20) },
                "title": { "text": BackdropName, "color": 4278190080, "size": 14, "font": "Arial" },
                "description": { "text": "", "color": 4278190080, "size": 14, "font": "Arial" },
                "color": fromRGBAtoInt(50, 50, 50, 255)
            };

            Backdrop.addBackdrop(node.parentNode(sNode), myBackdrop);
        }
    }

    function fromRGBAtoInt(r, g, b, a) {
        return ((a & 0xff) << 24) | ((r & 0xff) << 16) | ((g & 0xff) << 8) | (b & 0xff);
    }

    // Непосредственный вызов основной функции
    Molty_Backdrop();

})();
